import pytest
from calendar_core.slots import Event, parse_time, overlaps, free_slots, fmt_duration


def test_issue_hour_only_am():
    """'9am' -> 540."""
    assert parse_time("9am") == 540  # 9*60 = 540


def test_issue_hour_space_upper():
    """'9 AM' -> 540 with case-insensitive am/pm and optional space."""
    assert parse_time("9 AM") == 540  # 9*60 = 540


def test_issue_afternoon_minutes():
    """'2:30pm' -> 870."""
    assert parse_time("2:30pm") == 870  # (2+12)*60+30 = 14*60+30 = 870


def test_issue_noon():
    """'12pm' -> 720 (noon)."""
    assert parse_time("12pm") == 720  # 12*60 = 720


def test_issue_midnight():
    """'12am' -> 0 (midnight)."""
    assert parse_time("12am") == 0  # midnight = 0


def test_issue_after_midnight_minutes():
    """'12:15am' -> 15."""
    assert parse_time("12:15am") == 15  # 0*60+15 = 15


def test_issue_midday_minutes():
    """'12:30pm' stays at noon hour plus minutes."""
    assert parse_time("12:30pm") == 750  # 12*60+30 = 720+30 = 750


def test_issue_late_night_boundary():
    """'11:59pm' is the last minute of the day."""
    assert parse_time("11:59pm") == 1439  # 23*60+59 = 1380+59 = 1439


def test_issue_invalid_inputs_rejected():
    """Invalid input still raises ValueError."""
    for bad in ["13pm", "0am", "9:60am", "9", "pm", ""]:
        with pytest.raises(ValueError):
            parse_time(bad)


def test_contract_24h_still_works():
    """24-hour 'HH:MM' must keep working exactly as today."""
    assert parse_time("14:30") == 870  # 14*60+30 = 840+30 = 870


def test_contract_overlaps_back_to_back():
    """Back-to-back events (one ends exactly when the next starts) do not overlap."""
    assert overlaps(Event(60, 120), Event(120, 180)) is False  # share endpoint 120, no minute


def test_contract_free_slots_gaps():
    """free_slots returns the gaps inside [day_start, day_end) sorted by start."""
    result = free_slots([Event(120, 180), Event(60, 90)], 0, 200, 1)
    assert result == [(0, 60), (90, 120), (180, 200)]  # gaps [0,60), [90,120), [180,200)


def test_contract_fmt_duration():
    """fmt_duration renders 'Xh YYm' (e.g. 65 -> '1h 05m')."""
    assert fmt_duration(65) == "1h 05m"  # 65 = 60+5 -> 1h 05m
